from robot.libraries.BuiltIn import BuiltIn
import time

from taf.rfrl.l3_call.logger.l3_call_logger import log_result, log_operation, log_input_and_output
from taf.rfrl.l3_call.enviornment.classical_env.classical_env import ClassicalEnv
from taf.rfrl.l3_call.enviornment.exceptions import CannotFindRelatedLnCell
from taf.rfrl.l3_call.connection.api_connection.api_connection_factory import ApiConnectionFactory


class ClassicalEnvNSA(ClassicalEnv):
    def __init__(self):
        super(ClassicalEnvNSA, self).__init__()
        self._ran = "classical"
        self._mode = "NSA"
        self._node = "gnb"
        self._not_called_cells_distnames_gnb = []
        self._not_called_cells_distnames_enb = []
        self._connection_alias_enb = "l3_call_enb"
        self._connection_alias = "l3_call_gnb"
        self._delta_enb = None
        self._delta_gnb = None

    def __str__(self):
        return "ClassicalEnvNSA env instance for ran={}, mode={}, node={}".format(self._ran, self._mode,
                                                                                  self._node)

    def prepare_called_nrcell_from_enb_side(self, called_cell_distname):
        """
        Prepares called NRCELL from ENB side (makes sure it is
        unblocked and notBarred and changes defaultlnrelgnbcellid parameter)
        """
        self._cell = self._create_cell(cell_distname=called_cell_distname,
                                       bts_connection_alias=self._connection_alias)
        self._prepare_called_nrcell_from_enb_side()

    def _clean_up_after_call(self, close_connection_to_bts):
        self._open_connection_to_gnb_and_enb()
        self._make_enb_cells_callable()
        self._make_gnb_cells_callable()
        self._cell_ids = {}
        self._cell_ids_enb = {}
        self._called_cells_enb = {}
        self._called_cells.clear()

        if close_connection_to_bts:
            self._close_connection_to_gnb_and_enb()
        log_result("All cells unbarred/unblocked properly!")

    def _make_enb_cells_callable(self):
        self._delta_enb = self._create_delta(connection_alias=self._connection_alias_enb, id="l3_call_enb_delta_id")
        for not_called_cell_distname_enb in self._not_called_cells_distnames_enb:
            cell = self._create_cell(cell_distname=not_called_cell_distname_enb,
                                     bts_connection_alias=self._connection_alias_enb)
            cell.make_callable(delta=self._delta_enb)
        self._perform_delta_recommissioning(delta=self._delta_enb)
        time.sleep(20)

    def _make_gnb_cells_callable(self):
        self._delta_gnb = self._create_delta(connection_alias=self._connection_alias, id="l3_call_gnb_delta_id")
        for not_called_cell_distname_gnb in self._not_called_cells_distnames_gnb:
            cell = self._create_cell(cell_distname=not_called_cell_distname_gnb,
                                     bts_connection_alias=self._connection_alias)
            cell.make_callable(delta=self._delta_gnb)
        self._perform_delta_recommissioning(delta=self._delta_gnb)

    def _prepare_called_cell(self):
        self._get_cell_specific_info(distname=self._cell.distname)
        self._called_cell_spectrum = self._cell.get_spectrum(cells_info=self._cells_info,
                                                             cell_specific_info=self._cell_specific_info)
        self._cell.make_callable()

        if "NRCELL" in self._cell.distname:
            self._prepare_called_nrcell_from_enb_side()
        log_result("Cell {} is ready to be called!".format(self._cell.distname))

    def _prepare_called_nrcell_from_enb_side(self):
        relgnb_id, lncel_id = self._get_lncel_related_to_nrcell(called_nrcell_id=self._cell.get_cell_id())
        self._cell.enb_pair = self._construct_dist_name_for_lncel(lncel_id=lncel_id)
        cell_enb = self._create_cell(cell_distname=self._cell.enb_pair, bts_connection_alias=self._connection_alias_enb)
        cell_enb.make_callable()
        self._update_defaultlnrelgnbcellid_parameter(dist_name=self._cell.enb_pair, value=relgnb_id)

    def _prepare_not_called_cells(self):
        self._open_connection_to_gnb_and_enb()
        self._get_not_called_cells_distnames()
        self._prepare_not_called_cells_from_node(node="gnb")
        self._prepare_not_called_cells_from_node(node="enb")

    def _get_not_called_cells_distnames(self):
        all_cells_distnames_enb = self._connection.get_cells_distnames(connection=self._connection_alias_enb)
        all_cells_distnames_gnb = self._connection.get_cells_distnames(connection=self._connection_alias)
        distnames_of_cells_to_exclude = self._get_distnames_of_cells_to_exclude()

        self._not_called_cells_distnames_gnb = self._exclude_cells_from_all_cells_list(all_cells_distnames_gnb,
                                                                                       distnames_of_cells_to_exclude)
        self._not_called_cells_distnames_enb = self._exclude_cells_from_all_cells_list(all_cells_distnames_enb,
                                                                                       distnames_of_cells_to_exclude)
        log_result("List of not called cells enb: {} gnb: {}".format(self._not_called_cells_distnames_enb,
                                                                     self._not_called_cells_distnames_gnb))

    def _prepare_not_called_cells_from_node(self, node="gnb"):
        connection_alias = self._connection_alias if node == "gnb" else self._connection_alias_enb
        not_called_cells_distnames = self._not_called_cells_distnames_gnb if node == "gnb" \
            else self._not_called_cells_distnames_enb

        delta = self._create_delta(connection_alias=connection_alias, id=f"l3_call_{node}_delta_id")
        for not_called_cell_distname in not_called_cells_distnames:
            self._get_cell_specific_info(distname=not_called_cell_distname, node=node)
            self._prepare_not_called_cell(not_called_cell=not_called_cell_distname,
                                          connection_alias=connection_alias,
                                          delta=delta)
        self._perform_delta_recommissioning(delta=delta)

    def _prepare_not_called_cell(self, not_called_cell, connection_alias, delta):
        cell = self._create_cell(cell_distname=not_called_cell, bts_connection_alias=connection_alias)
        cell_spectrum = cell.get_spectrum(cells_info=self._cells_info,
                                          cell_specific_info=self._cell_specific_info)
        shared_spectrum = self._is_spectrum_shared(cell_spectrum_1=self._called_cell_spectrum,
                                                   cell_spectrum_2=cell_spectrum)

        if shared_spectrum:
            cell = self._create_cell(cell_distname=not_called_cell, shared_spectrum=shared_spectrum,
                                     bts_connection_alias=connection_alias)
        cell.make_uncallable(delta=delta)

    def _get_lncel_related_to_nrcell(self, called_nrcell_id):
        relations = self._get_lncel_to_nrcell_relations()
        for nrcell in relations:
            if int(nrcell) == called_nrcell_id:
                return relations[nrcell]["relgnb_id"], relations[nrcell]["lncel_id"]

        raise CannotFindRelatedLnCell("Cell with nrCellId {} is not related to any LNCEL".format(called_nrcell_id))

    def _get_lncel_to_nrcell_relations(self):
        self._open_api_connection(node="enb")
        lnrelgnbcell_managed_objects = self._connection.get_managed_objects(connection=self._connection_alias_enb,
                                                                            class_name="LNRELGNBCELL_A")
        return self._get_relations_dict(lnrelgnbcell_managed_objects=lnrelgnbcell_managed_objects)

    @log_input_and_output
    def _get_relations_dict(self, lnrelgnbcell_managed_objects):
        relations = {}
        for managed_object in lnrelgnbcell_managed_objects:
            lncel_id = int(managed_object["distName"].split("/")[-2].split("-")[-1])
            nrcell_id = managed_object["parameters"]["nrCellId"]
            relgnb_id = int(managed_object["distName"].split("/")[-1].split("-")[-1])
            relations[nrcell_id] = {"relgnb_id": relgnb_id, "lncel_id": lncel_id}

        return relations

    def _open_api_connection(self, node="gnb"):
        self._connection = ApiConnectionFactory.create_connection(ran="classical", node=node)
        alias = self._connection_alias if node == "gnb" else self._connection_alias_enb
        self._connection.connect_to(name=alias)

    def _get_cell_specific_info(self, distname, node="gnb"):
        alias = self._connection_alias if node == "gnb" else self._connection_alias_enb
        self._cell_specific_info = self._connection.get_cell_specific_info(connection=alias, distname=distname)

    def _update_defaultlnrelgnbcellid_parameter(self, dist_name, value):
        log_operation("Performing recommissioning of defaultLnRelGnbCellId "
                      "parameter for cell {} to value {}".format(dist_name, value))
        self._connection.perform_parameter_recommissioning(dist_name=dist_name,
                                                           parameter="defaultLnRelGnbCellId",
                                                           operation="update",
                                                           value=value,
                                                           connection=self._connection_alias_enb)

    def _construct_dist_name_for_lncel(self, lncel_id):
        enbs_details = BuiltIn().get_variable_value("${tl.enbs[0]}")
        mrbts_id = enbs_details.instance_id
        lnbts_id = enbs_details.global_bts_id
        return "MRBTS-{}/LNBTS-{}/LNCEL-{}".format(mrbts_id, lnbts_id, lncel_id)

    def _get_cell_id(self, called_cell_distname):
        self._cell = self._create_cell(cell_distname=called_cell_distname, bts_connection_alias=self._connection_alias)
        self._cell.id = self._cell.get_cell_id()

        if "NRCELL" in self._cell.distname:
            relgnb_id, lncel_id = self._get_lncel_related_to_nrcell(called_nrcell_id=self._cell.id)
            self._cell.enb_pair = self._construct_dist_name_for_lncel(lncel_id=lncel_id)
            cell_enb = self._create_cell(cell_distname=self._cell.enb_pair,
                                         bts_connection_alias=self._connection_alias_enb)
            self._cell.enb_pair_id = cell_enb.get_cell_id()
        return self._make_cell_ids_dict()

    def _make_cell_ids_dict(self):
        cell_ids = {"gnb_cell": self._cell.id}
        if self._cell.enb_pair:
            cell_ids["enb_cell"] = self._cell.enb_pair_id
        return cell_ids

    def _open_connection_to_gnb_and_enb(self):
        self._open_api_connection()
        self._open_api_connection(node="enb")

    def _close_connection_to_gnb_and_enb(self):
        self._connection.disconnect(connection=self._connection_alias)
        self._connection.disconnect(connection=self._connection_alias_enb)
